# ── 嵌入数据 ──────────────────────────────────────────────────────────────────
_ONLINE_B64  = ""
_OFFLINE_B64 = ""


# ── 数据加载 ──────────────────────────────────────────────────────────────────
@st.cache_data
def load_data():
    df_on = pd.read_excel(io.BytesIO(base64.b64decode(_ONLINE_B64)))

    # 仅保留 Nic Salt 数据（线上最终应为100条）
    if '产品类型' in df_on.columns:
        pt = df_on['产品类型'].fillna('').astype(str)
        df_on = df_on[
            pt.str.contains(r'nic\s*salt', case=False, regex=True)
        ].reset_index(drop=True)

    raw   = pd.read_excel(io.BytesIO(base64.b64decode(_OFFLINE_B64)), sheet_name="调研表", header=0)
    df_off = raw.iloc[1:].reset_index(drop=True)
    df_off.columns = raw.columns
    return df_on, df_off

df_online, df_offline = load_data()

# ── 含冰修正："/"为不确定，需从名称/标签推断 ─────────────────────────────────
ICE_RE = r'\bice\b|\bmenthol\b|\bmint\b|\bcool\b|\bfrost\b|\barctic\b|\bcooler\b|\bchill\b'
_n = df_online['口味名称'].str.lower().fillna('')
_t = df_online['口味标签'].str.lower().fillna('')
df_online['含冰_修正'] = (_n.str.contains(ICE_RE) | _t.str.contains(ICE_RE)).map({True:'是',False:'否'})
ice_pct = round(df_online['含冰_修正'].eq('是').mean()*100,1)

# ── 线上品牌归一化 ────────────────────────────────────────────────────────────
BRAND_MAP = {
    'elfbar':'Elfbar','elf bar':'Elfbar',
    'lost mary':'Lost Mary','lostmary':'Lost Mary',
    'hayati':'Hayati','haiyati':'Hayati',
    'ske':'SKE','elux':'Elux','elux liquid':'Elux',
    'elfliq':'Elfliq','efliq':'Elfliq','elf liquid':'Elfliq',
    'pod salt':'Pod Salt','bar juice':'Bar Juice','barjuice':'Bar Juice',
    'bar juce':'Bar Juice','ivg':'IVG','riot':'Riot','nasty':'Nasty',
    'dinner lady':'Dinner Lady','asin':'Asin','pixl':'Pixl',
    'vampire vape':'Vampire Vape',
}
def nb(b):
    k=str(b).strip().lower()
    return BRAND_MAP.get(k, str(b).strip().title())

def split_brands(text):
    if pd.isna(text): return []
    return [nb(x) for x in re.split(r'[;，,]+',str(text))
            if x.strip() and x.strip().lower() not in ('nan','none','')]

online_brand_c = Counter(nb(str(b)) for b in df_online['品牌'])
offline_brand_c  = Counter()
offline_rec_c    = Counter()
for _, r in df_offline.iterrows():
    offline_brand_c.update(split_brands(r.get('畅销烟油品牌','')))
    offline_rec_c.update(split_brands(r.get('推荐烟油产品','')))

# ── 精准口味匹配（逐条核验） ─────────────────────────────────────────────────
FLAVOR_RULES = {
    'Cherry Ice':               r'\bcherry ice\b|^cherry$',
    'Lemon Lime':               r'lemon.{0,5}lime',
    'Blue Razz':                r'blue razz',
    'Fresh Mint':               r'^fresh mint$|\bspearmint\b',
    'Pink Lemonade':            r'^pink lemonade$',
    'Blue Sour Raspberry':      r'blue sour raspberry|blueberry sour raspberry',
    'Blueberry':                r'^blueberry$',
    'Apple Peach':              r'^apple peach$',
    'Watermelon Ice':           r'^watermelon ice$',
    'Tobacco':                  r'tobacco',
    'Grape Ice':                r'^grape$|^grape ice$',
    'Mr Blue':                  r'^mr\.?\s*blue$',
    'Fuzzy Cherry':             r'fizzy cherry|fuzzy cherry',
    'Kiwi':                     r'\bkiwi\b',
    'Blueberry Gummy Cranberry':r'blueberry.*cranberry',
}

def online_match(pattern):
    mask = df_online['口味名称'].str.lower().fillna('').str.contains(pattern, regex=True)
    return int(mask.sum()), df_online[mask]['口味名称'].unique().tolist()

def extract_flavors(text):
    if pd.isna(text): return []
    result=[]
    for seg in re.split(r'[;；]+', str(text)):
        seg=seg.strip()
        if ':' in seg: seg=seg.split(':',1)[1].strip()
        for f in re.split(r'[,，]+', seg):
            f=f.strip().lower()
            if f and f not in ('nan','none','') and len(f)>2:
                result.append(f)
    return result

offline_flavor_c = Counter()
for _, r in df_offline.iterrows():
    offline_flavor_c.update(extract_flavors(r.get('最畅销烟油口味','')))
    offline_flavor_c.update(extract_flavors(r.get('店员最喜欢品牌+口味','')))

cross_data=[]
for flavor, pattern in FLAVOR_RULES.items():
    on_cnt, on_names = online_match(pattern)
    off_cnt = offline_flavor_c.get(flavor.lower(), 0)
    status = ('✅ 双源印证' if on_cnt>=2 and off_cnt>=2
              else ('🔵 线上领先' if on_cnt>=3 and off_cnt<2
              else ('⚠️ 线下独有' if off_cnt>=2 and on_cnt<2
              else '— 小众')))
    cross_data.append({
        '口味': flavor,
        '线下门店提及次数': off_cnt,
        '线上榜单条目数':  on_cnt,
        '线上匹配品名':   '、'.join(on_names) if on_names else '—',
        '验证状态':       status,
    })
df_cross = pd.DataFrame(cross_data).sort_values('线下门店提及次数', ascending=False)

# ── 口感点统计 ────────────────────────────────────────────────────────────────
taste_c = Counter()
for t in df_offline['最在意口感点'].dropna():
    for s in re.split(r'[;，,]+', str(t)):
        s=s.strip()
        if s and s.lower() not in ('nan','none'): taste_c[s]+=1

# ── 品牌竞争优势 ─────────────────────────────────────────────────────────────
adv_c = Counter()
for t in df_offline['品牌竞争优势'].dropna():
    for s in re.split(r'[;，,]+', str(t)):
        s=s.strip()
        if s and s.lower() not in ('nan','none'): adv_c[s]+=1

