    # 准备数据
    on_brand_df  = pd.DataFrame(online_brand_c.most_common(12),  columns=['品牌','线上上榜次数'])
    off_brand_df = pd.DataFrame(offline_brand_c.most_common(12), columns=['品牌','线下门店提及次数'])
    rec_brand_df = pd.DataFrame(offline_rec_c.most_common(12),   columns=['品牌','线下推荐次数'])

